package com.wanyuecity.energy.inspection;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.google.zxing.BarcodeFormat;
import com.google.zxing.client.j2se.MatrixToImageWriter;
import com.google.zxing.common.BitMatrix;
import com.google.zxing.qrcode.QRCodeWriter;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

import java.io.ByteArrayOutputStream;
import java.sql.Date;
import java.time.LocalDate;
import java.util.*;

@Service @RequiredArgsConstructor
public class InspectionEquipmentService {
    private final JdbcTemplate jdbc; private final ObjectMapper json;
    @Value("${energy.public-base-url:https://auto.apperload.com}") private String publicBaseUrl;

    public List<Map<String,Object>> categories(){
        List<Map<String,Object>> rows=jdbc.queryForList("SELECT id,code,name,system_name systemName,base_fields_json baseFieldsJson,description,enabled,sort_order sortOrder,created_at createdAt,updated_at updatedAt FROM inspection_equipment_category ORDER BY enabled DESC,sort_order,id");
        for(Map<String,Object> r:rows)r.put("templates",jdbc.queryForList("SELECT x.id,x.template_id templateId,t.name templateName,x.inspection_kind inspectionKind,x.enabled FROM inspection_category_template x JOIN inspection_template t ON t.id=x.template_id WHERE x.category_id=? ORDER BY x.inspection_kind,t.name",r.get("id")));
        return rows;
    }
    @Transactional public Map<String,Object> saveCategory(Long id,Map<String,Object>b){required(b,"code","分类编码不能为空");required(b,"name","分类名称不能为空");String fields=jsonText(b.get("baseFields"));if(id==null){jdbc.update("INSERT INTO inspection_equipment_category(code,name,system_name,base_fields_json,description,enabled,sort_order) VALUES(?,?,?,?,?,?,?)",text(b,"code").toUpperCase(),text(b,"name"),text(b,"systemName"),fields,text(b,"description"),boolInt(b,"enabled",1),intValue(b.get("sortOrder"),0));id=lastId();}else jdbc.update("UPDATE inspection_equipment_category SET code=?,name=?,system_name=?,base_fields_json=?,description=?,enabled=?,sort_order=? WHERE id=?",text(b,"code").toUpperCase(),text(b,"name"),text(b,"systemName"),fields,text(b,"description"),boolInt(b,"enabled",1),intValue(b.get("sortOrder"),0),id);saveCategoryTemplates(id,b.get("templates"));return category(id);}
    private void saveCategoryTemplates(Long id,Object value){jdbc.update("DELETE FROM inspection_category_template WHERE category_id=?",id);if(value instanceof List<?> list)for(Object o:list)if(o instanceof Map<?,?>m&&longValue(m.get("templateId"))!=null)jdbc.update("INSERT INTO inspection_category_template(category_id,template_id,inspection_kind,enabled) VALUES(?,?,?,1)",id,longValue(m.get("templateId")),defaultText(m,"inspectionKind","ROUTINE"));}
    public Map<String,Object> category(Long id){Map<String,Object> r=one("SELECT id,code,name,system_name systemName,base_fields_json baseFieldsJson,description,enabled,sort_order sortOrder FROM inspection_equipment_category WHERE id=?",id);r.put("templates",jdbc.queryForList("SELECT id,template_id templateId,inspection_kind inspectionKind FROM inspection_category_template WHERE category_id=? AND enabled=1",id));return r;}

    public List<Map<String,Object>> equipment(String keyword,Long categoryId,Integer enabled){StringBuilder sql=new StringBuilder("SELECT e.id,e.equipment_code equipmentCode,e.equipment_name equipmentName,e.category_id categoryId,c.name categoryName,e.system_name systemName,e.installation_location installationLocation,e.floor_code floorCode,e.area_name areaName,e.brand,e.model,e.specification,e.serial_number serialNumber,e.commissioned_date commissionedDate,e.responsible_department responsibleDepartment,e.responsible_person responsiblePerson,e.responsible_phone responsiblePhone,e.equipment_status equipmentStatus,e.importance_level importanceLevel,e.maintenance_company maintenanceCompany,e.maintenance_phone maintenancePhone,e.next_maintenance_date nextMaintenanceDate,e.attributes_json attributesJson,e.qr_token qrToken,e.remark,e.enabled,e.updated_at updatedAt FROM inspection_equipment e JOIN inspection_equipment_category c ON c.id=e.category_id WHERE 1=1");List<Object>a=new ArrayList<>();if(keyword!=null&&!keyword.isBlank()){sql.append(" AND (e.equipment_code LIKE ? OR e.equipment_name LIKE ? OR e.serial_number LIKE ? OR e.installation_location LIKE ?)");String k="%"+keyword.trim()+"%";Collections.addAll(a,k,k,k,k);}if(categoryId!=null){sql.append(" AND e.category_id=?");a.add(categoryId);}if(enabled!=null){sql.append(" AND e.enabled=?");a.add(enabled);}sql.append(" ORDER BY e.enabled DESC,c.sort_order,e.equipment_code LIMIT 1000");return jdbc.queryForList(sql.toString(),a.toArray());}
    @Transactional public Map<String,Object> saveEquipment(Long id,Map<String,Object>b){required(b,"equipmentCode","设备编号不能为空");required(b,"equipmentName","设备名称不能为空");Long categoryId=longValue(b.get("categoryId"));if(categoryId==null)bad("请选择设备分类");String attrs=jsonText(b.get("attributes"));Object[] args={text(b,"equipmentCode"),text(b,"equipmentName"),categoryId,text(b,"systemName"),text(b,"installationLocation"),text(b,"floorCode"),text(b,"areaName"),text(b,"brand"),text(b,"model"),text(b,"specification"),text(b,"serialNumber"),date(b.get("commissionedDate")),text(b,"responsibleDepartment"),text(b,"responsiblePerson"),text(b,"responsiblePhone"),defaultText(b,"equipmentStatus","IN_USE"),defaultText(b,"importanceLevel","NORMAL"),text(b,"maintenanceCompany"),text(b,"maintenancePhone"),date(b.get("nextMaintenanceDate")),attrs,text(b,"remark"),boolInt(b,"enabled",1)};if(id==null){Object[] insert=Arrays.copyOf(args,args.length+1);insert[args.length]=UUID.randomUUID().toString().replace("-","");jdbc.update("INSERT INTO inspection_equipment(equipment_code,equipment_name,category_id,system_name,installation_location,floor_code,area_name,brand,model,specification,serial_number,commissioned_date,responsible_department,responsible_person,responsible_phone,equipment_status,importance_level,maintenance_company,maintenance_phone,next_maintenance_date,attributes_json,remark,enabled,qr_token) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",insert);id=lastId();}else{Object[] update=Arrays.copyOf(args,args.length+1);update[args.length]=id;jdbc.update("UPDATE inspection_equipment SET equipment_code=?,equipment_name=?,category_id=?,system_name=?,installation_location=?,floor_code=?,area_name=?,brand=?,model=?,specification=?,serial_number=?,commissioned_date=?,responsible_department=?,responsible_person=?,responsible_phone=?,equipment_status=?,importance_level=?,maintenance_company=?,maintenance_phone=?,next_maintenance_date=?,attributes_json=?,remark=?,enabled=? WHERE id=?",update);}return equipmentById(id);}
    public Map<String,Object> equipmentById(Long id){Map<String,Object>r=one("SELECT e.*,e.equipment_code equipmentCode,e.equipment_name equipmentName,e.category_id categoryId,c.name categoryName,c.base_fields_json baseFieldsJson,e.system_name systemName,e.installation_location installationLocation,e.floor_code floorCode,e.area_name areaName,e.serial_number serialNumber,e.commissioned_date commissionedDate,e.responsible_department responsibleDepartment,e.responsible_person responsiblePerson,e.responsible_phone responsiblePhone,e.equipment_status equipmentStatus,e.importance_level importanceLevel,e.maintenance_company maintenanceCompany,e.maintenance_phone maintenancePhone,e.next_maintenance_date nextMaintenanceDate,e.attributes_json attributesJson,e.qr_token qrToken FROM inspection_equipment e JOIN inspection_equipment_category c ON c.id=e.category_id WHERE e.id=?",id);r.put("templates",jdbc.queryForList("SELECT t.id,t.name,x.inspection_kind inspectionKind,t.fields_json fieldsJson FROM inspection_category_template x JOIN inspection_template t ON t.id=x.template_id WHERE x.category_id=? AND x.enabled=1 AND t.enabled=1",r.get("categoryId")));return r;}
    public Map<String,Object> byToken(String token){Map<String,Object>r=one("SELECT id FROM inspection_equipment WHERE qr_token=? AND enabled=1",token);Map<String,Object>e=equipmentById(longValue(r.get("id")));e.put("pendingTasks",jdbc.queryForList("SELECT id,task_no taskNo,status,scheduled_at scheduledAt,due_at dueAt,access_token accessToken FROM inspection_task WHERE target_type='INSPECTION_EQUIPMENT' AND target_id=? AND status IN ('PENDING','IN_PROGRESS','OVERDUE') ORDER BY scheduled_at",String.valueOf(e.get("id"))));return e;}
    public byte[] qr(String token){byToken(token);try{String url=publicBaseUrl.replaceAll("/$","")+"/inspection/equipment/"+token;BitMatrix m=new QRCodeWriter().encode(url,BarcodeFormat.QR_CODE,420,420);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(m,"PNG",out);return out.toByteArray();}catch(Exception ex){bad("设备二维码生成失败");return new byte[0];}}

    private Map<String,Object> one(String s,Object...a){List<Map<String,Object>>l=jdbc.queryForList(s,a);if(l.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"数据不存在");return new LinkedHashMap<>(l.get(0));}private Long lastId(){return jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);}private void required(Map<?,?>m,String k,String msg){if(text(m,k).isBlank())bad(msg);}private void bad(String s){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,s);}private String jsonText(Object o){if(o==null)return "[]";if(o instanceof String s)return s.isBlank()?"[]":s;try{return json.writeValueAsString(o);}catch(JsonProcessingException e){bad("JSON格式错误");return "[]";}}
    private static String text(Map<?,?>m,String k){Object o=m.get(k);return o==null?"":String.valueOf(o).trim();}private static String defaultText(Map<?,?>m,String k,String d){String s=text(m,k);return s.isBlank()?d:s;}private static Long longValue(Object o){if(o==null||String.valueOf(o).isBlank())return null;return o instanceof Number n?n.longValue():Long.valueOf(String.valueOf(o));}private static int intValue(Object o,int d){if(o==null||String.valueOf(o).isBlank())return d;return o instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(o));}private static int boolInt(Map<?,?>m,String k,int d){Object o=m.get(k);if(o==null)return d;if(o instanceof Boolean b)return b?1:0;return intValue(o,d);}private static Date date(Object o){if(o==null||String.valueOf(o).isBlank())return null;return Date.valueOf(LocalDate.parse(String.valueOf(o).substring(0,10)));}
}
